"""Retain unmodified Native actor readbacks for saved-only U-turn measurement."""

import json
from math import hypot, isfinite
from pathlib import Path

from u_turn_measurement import PROHIBITIONS


def _body(actor):
    location = actor.get_transform().location
    extent = actor.bounding_box.extent
    velocity = actor.get_velocity()
    values = [float(location.x), float(location.y), float(extent.x),
              float(extent.y), float(velocity.x), float(velocity.y)]
    if not all(isfinite(value) for value in values) or min(values[2:4]) <= 0:
        raise ValueError("Native actor body or velocity invalid")
    return {'x_m': values[0], 'y_m': values[1],
            'body_radius_m': hypot(values[2], values[3]),
            'speed_mps': hypot(values[4], values[5])}


class UTurnSourceRecorder:
    def __init__(self, directory, ego, participants, scene, *, device=None):
        self.root = Path(directory)
        self.ego = ego
        self.participants = dict(participants)
        if set(self.participants) != {'oncoming', 'following'}:
            raise ValueError("Original oncoming and following actors required")
        identities = [int(ego.id)] + [int(a.id) for a in self.participants.values()]
        if len(set(identities)) != 3:
            raise ValueError("Original actor identities must differ")
        self.ids = {role: str(int(actor.id)) for role, actor in self.participants.items()}
        context = {
            'format': 'worker-u-turn-original-context',
            'approach_road_id': scene['road_id'],
            'approach_lane_id': scene['approach_lane_id'],
            'opposite_lane_id': scene['opposite_lane_id'],
            'participant_roles': {
                self.ids[role]: {
                    'role': role,
                    'source_ref': 'u_turn_motion.jsonl#participants/' + self.ids[role]}
                for role in ('oncoming', 'following')},
            'prohibitions': {
                law: {'value': None, 'source_ref': None} for law in PROHIBITIONS},
            'legal_safety_judgment': None,
            'physical_completion_verified': False}
        path = self.root / 'u_turn_context.json'
        if path.exists():
            raise ValueError("Retain prior original U-turn context")
        path.write_text(json.dumps(context, indent=2, allow_nan=False) + '\n')
        if device is not None:
            observation = {
                'mapped_no_u_turn_device': {
                    'landmark_id': device['landmark_id'],
                    'road_id': device['road_id'],
                    'distance_to_approach_m': device['distance_to_approach_m'],
                    'source_fields': device['source_fields'],
                    'official_device_status': None,
                    'governing_lane_status': None,
                    'pixel_visibility_status': None}}
            (self.root/'u_turn_device.json').write_text(
                json.dumps(observation, indent=2, allow_nan=False)+'\n')
        self.stream = (self.root / 'u_turn_motion.jsonl').open('x', encoding='utf-8')
        self.previous = None

    def append(self, frame, time_s):
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError("Native U-turn frame/time invalid")
        if self.previous is not None and (frame != self.previous[0] + 1 or
                abs(time_s - self.previous[1] - .05) > 1e-4):
            raise ValueError("Native U-turn 20 Hz source discontinuity")
        transform = self.ego.get_transform()
        yaw = float(transform.rotation.yaw)
        if not isfinite(yaw):
            raise ValueError("Native U-turn yaw invalid")
        row = {'frame': frame, 'time_s': time_s,
               'ego_id': int(self.ego.id),
               'ego': _body(self.ego), 'ego_yaw_deg': yaw,
               'participants': {self.ids[role]: _body(actor)
                                for role, actor in self.participants.items()}}
        self.stream.write(json.dumps(row, allow_nan=False) + '\n')
        self.stream.flush()
        self.previous = frame, time_s
        return row

    def close(self):
        self.stream.close()

"""Original-frame U-turn motion and surrounding-user safety observations.

This measures geometry over the maneuver without deciding whether it was safe
or whether a cited cross-reference prohibits the turn.
"""

from hashlib import sha256
import json
from math import atan2, cos, hypot, isfinite, radians, sin
from pathlib import Path


PROHIBITIONS = ('NRS-484B-403-2', 'NRS-484B-403-3', 'NRS-484B-227-1',
                'NRS-484B-363-3', 'NRS-484B-407')


def _load(path, name):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing original source: ' + name)
    raw = path.read_bytes()
    try:
        return json.loads(raw) if path.suffix == '.json' else [json.loads(line) for line in raw.splitlines()], sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original source: ' + name) from error


def _body(body, label):
    try:
        values = tuple(float(body[key]) for key in ('x_m', 'y_m', 'body_radius_m'))
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError('Missing original body geometry: ' + label) from error
    if not all(isfinite(v) for v in values) or values[2] <= 0:
        raise ValueError('Invalid original body geometry: ' + label)
    return values


def measure(motion_path, context_path):
    rows, motion_sha = _load(motion_path, 'u_turn_motion.jsonl')
    context, context_sha = _load(context_path, 'u_turn_context.json')
    if not isinstance(rows, list) or len(rows) < 3 or not isinstance(context, dict):
        raise ValueError('Original U-turn source incomplete')
    prohibitions = context.get('prohibitions')
    if not isinstance(prohibitions, dict) or set(prohibitions) != set(PROHIBITIONS):
        raise ValueError('Every cited U-turn prohibition needs context')
    for name, item in prohibitions.items():
        if not isinstance(item, dict) or 'value' not in item:
            raise ValueError('Cited prohibition context missing: ' + name)
        value, source = item['value'], item.get('source_ref')
        if value is not None and (type(value) is not bool or not isinstance(source, str) or not source):
            raise ValueError('Known prohibition needs cited source: ' + name)
        if value is None and source is not None:
            raise ValueError('Unknown prohibition cannot assert a source verdict: ' + name)
    roles = context.get('participant_roles')
    if not isinstance(roles, dict) or not roles:
        raise ValueError('Original surrounding participant roles required')
    for name, item in roles.items():
        if not isinstance(name, str) or not name or not isinstance(item, dict) or (
                item.get('role') not in ('oncoming', 'following', 'other') or
                not item.get('source_ref')):
            raise ValueError('Participant role needs a cited original source')
    start_yaw = None
    previous = None
    observations = []
    minimum_gap = {actor_id: float('inf') for actor_id in roles}
    minimum_accel = {actor_id: None for actor_id in roles}
    previous_speeds = {}
    for row in rows:
        frame, time_s = row.get('frame'), row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original U-turn frame/time invalid')
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > 1e-4):
            raise ValueError('Original U-turn frames are not joined at 20 Hz')
        previous = frame, time_s
        ego = _body(row.get('ego'), 'ego')
        bodies = row.get('participants')
        if not isinstance(bodies, dict) or set(bodies) != set(roles):
            raise ValueError('Original U-turn participant identities differ')
        try:
            yaw = float(row['ego_yaw_deg'])
        except (KeyError, TypeError, ValueError) as error:
            raise ValueError('Original U-turn yaw missing') from error
        if not isfinite(yaw):
            raise ValueError('Original U-turn yaw invalid')
        if start_yaw is None:
            start_yaw = yaw
        delta = atan2(sin(radians(yaw - start_yaw)), cos(radians(yaw - start_yaw))) * 180 / 3.141592653589793
        gaps = {}
        for actor_id in roles:
            body = _body(bodies[actor_id], actor_id)
            gap = hypot(ego[0] - body[0], ego[1] - body[1]) - ego[2] - body[2]
            gaps[actor_id] = gap
            minimum_gap[actor_id] = min(minimum_gap[actor_id], gap)
            try:
                speed = float(bodies[actor_id]['speed_mps'])
            except (KeyError, TypeError, ValueError) as error:
                raise ValueError('Original participant speed missing') from error
            if not isfinite(speed) or speed < 0:
                raise ValueError('Original participant speed invalid')
            if actor_id in previous_speeds:
                accel = (speed - previous_speeds[actor_id]) / .05
                old = minimum_accel[actor_id]
                minimum_accel[actor_id] = accel if old is None else min(old, accel)
            previous_speeds[actor_id] = speed
        observations.append({'frame': frame, 'time_s': time_s,
                             'heading_change_deg': delta, 'surface_gaps_m': gaps})
    onset = next((index for index, row in enumerate(observations)
                  if abs(row['heading_change_deg']) > .5), None)
    if onset is None or onset == 0:
        raise ValueError('No measured U-turn heading-change onset')
    return {'format': 'worker-u-turn-observation',
            'sources': {'u_turn_motion.jsonl': motion_sha,
                        'u_turn_context.json': context_sha},
            'turn_onset_frame': observations[onset]['frame'],
            'last_observed_frame': observations[-1]['frame'],
            'net_heading_change_deg': observations[-1]['heading_change_deg'],
            'participant_minimum_surface_gap_m': minimum_gap,
            'participant_minimum_sampled_acceleration_mps2': minimum_accel,
            'participant_roles': roles, 'prohibition_context': prohibitions,
            'observations': observations,
            'safe_turn_legal_judgment': None,
            'prohibition_legal_judgments': None}

"""Four synchronized original RGB source streams for marked-lane cases."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown lane source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior lane camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original lane camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Lane source encoder failed")


class LaneCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named lane source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original lane camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original lane camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Lane source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original lane source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original lane camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from u_turn_363_school import measure_school_candidate


def scene():
    waypoint = SimpleNamespace(road_id=7, lane_id=-1,
        transform=SimpleNamespace(location=SimpleNamespace(x=0, y=0)))
    return {'approach': waypoint}


def sign(label='SCHOOL ZONE', *, road_id=7, xy=(10, 2)):
    return {'landmark_id': 'A', 'road_id': road_id, 'xy_m': list(xy),
            'name': label, 'type': '274', 'value': ''}


class SchoolCandidateTests(unittest.TestCase):
    def test_mapped_candidate_retains_all_exception_unknowns(self):
        packet = measure_school_candidate(scene(), [sign()])
        self.assertEqual(packet['matching_landmarks'][0]['landmark_id'], 'A')
        for key in ('official_zone_designation', 'children_present',
                    'school_in_session', 'governing_body_exempt_period',
                    'operational_beacon', 'pupils_in_class',
                    'yellow_beacon_lights_flashing',
                    'sign_speed_limit_in_effect',
                    'legal_prohibition_applicable'):
            self.assertIsNone(packet[key])

    def test_wrong_road_and_distant_sign_rejected(self):
        with self.assertRaisesRegex(ValueError, 'No source-mapped'):
            measure_school_candidate(scene(), [sign(road_id=8), sign(xy=(100, 0))])

    def test_generic_school_word_is_not_zone_designation_candidate(self):
        with self.assertRaisesRegex(ValueError, 'No source-mapped'):
            measure_school_candidate(scene(), [sign('SCHOOL BUS')])


if __name__ == '__main__':
    unittest.main()
